<?php
declare(strict_types=1); namespace App\Models\Finance; use Illuminate\Database\Eloquent\Model;
class StudentInvoice extends Model { protected $table='student_invoices'; protected $guarded=[]; protected function casts():array{return ['billing_month'=>'date','issue_date'=>'date','due_date'=>'date','cancelled_at'=>'datetime','subtotal'=>'decimal:2','discount'=>'decimal:2','penalty'=>'decimal:2','total'=>'decimal:2','paid_amount'=>'decimal:2','outstanding_amount'=>'decimal:2'];} public function student(){return $this->belongsTo(\App\Models\Student::class);} public function academicYear(){return $this->belongsTo(\App\Models\AcademicYear::class);} public function semester(){return $this->belongsTo(\App\Models\Semester::class);} public function items(){return $this->hasMany(StudentInvoiceItem::class,'invoice_id');} public function payments(){return $this->hasMany(StudentPayment::class,'invoice_id');} }
